#define WRAPPERS_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint64_t wrap_rbtree_run(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t wrap_rbtree_insert_seq(uint64_t seed, int64_t n_i);
uint64_t wrap_rbtree_erase_all(uint64_t seed, int64_t n_i);
uint64_t wrap_rbtree_find(uint64_t seed, int64_t n_i, int64_t seed2);
uint64_t wrap_rbtree_cached(uint64_t seed, int64_t nops_i);
uint64_t wrap_rbtree_linked(uint64_t seed, int64_t nops_i);
uint64_t wrap_rbtree_augmented(uint64_t seed, int64_t nops_i);
uint64_t wrap_rbtree_postorder(uint64_t seed, int64_t n_i);
uint64_t wrap_rb_replace(uint64_t seed, int64_t n_i, int64_t k_i);

/* The same functions under `rust_anything_` names, for shadow runs. */
uint64_t rust_anything_wrap_rbtree_run(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t rust_anything_wrap_rbtree_insert_seq(uint64_t seed, int64_t n_i);
uint64_t rust_anything_wrap_rbtree_erase_all(uint64_t seed, int64_t n_i);
uint64_t rust_anything_wrap_rbtree_find(uint64_t seed, int64_t n_i, int64_t seed2);
uint64_t rust_anything_wrap_rbtree_cached(uint64_t seed, int64_t nops_i);
uint64_t rust_anything_wrap_rbtree_linked(uint64_t seed, int64_t nops_i);
uint64_t rust_anything_wrap_rbtree_augmented(uint64_t seed, int64_t nops_i);
uint64_t rust_anything_wrap_rbtree_postorder(uint64_t seed, int64_t n_i);
uint64_t rust_anything_wrap_rb_replace(uint64_t seed, int64_t n_i, int64_t k_i);

#endif /* WRAPPERS_RS_H */
